/*
 * A115731  Permutation of natural numbers generated by 3-rowed array shown
 *          below.
 * https://oeis.org/A115731
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 2*a(n-1) - 2*a(n-2) + 2*a(n-3) - 2*a(n-4) + 2*a(n-5) -
 *            a(n-6) for n>9, with initial values a(1..9) =
 *            {1,6,2,7,5,3,12,8,4}
 * Range:     u8 n <= 252, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of previously computed terms */
    static seq_t *seq = NULL;
    static idx_t cached = 0;        /* number of terms currently cached */

    /* pre‑computed first nine terms */
    static const seq_t base[9] = { (seq_t)1, (seq_t)6, (seq_t)2,
                                   (seq_t)7, (seq_t)5, (seq_t)3,
                                   (seq_t)12,(seq_t)8, (seq_t)4 };

    if (n == 0) return 0;           /* undefined for n<1, return 0 */

    /* enlarge cache if necessary */
    if (n > cached) {
        idx_t new_size = n;
        seq = (seq_t *)realloc(seq, new_size * sizeof(seq_t));
        if (!seq) exit(1);          /* memory allocation failed */

        /* compute missing values */
        for (idx_t i = cached + 1; i <= n; ++i) {
            if (i <= 9) {
                seq[i - 1] = base[i - 1];
            } else {
                /* recurrence:
                   a(i) = 2*a(i-1) - 2*a(i-2) + 2*a(i-3) - 2*a(i-4)
                          + 2*a(i-5) - a(i-6)                            */
                seq[i - 1] = 2 * seq[i - 2]
                           - 2 * seq[i - 3]
                           + 2 * seq[i - 4]
                           - 2 * seq[i - 5]
                           + 2 * seq[i - 6]
                           - seq[i - 7];
            }
        }
        cached = n;
    }
    return seq[n - 1];
}
